package android.app.job;import android.content.*;import android.net.*;public class JobInfo {public static final int BACKOFF_POLICY_EXPONENTIAL=1;public int id,policy;public boolean persisted;public long interval,flex,latency,backoff;public NetworkRequest network;public ComponentName service;public static class Builder {final JobInfo v=new JobInfo();public Builder(int id,ComponentName s){v.id=id;v.service=s;}public Builder setPersisted(boolean b){v.persisted=b;return this;}public Builder setBackoffCriteria(long t,int p){v.backoff=t;v.policy=p;return this;}public Builder setPeriodic(long i,long f){v.interval=i;v.flex=f;return this;}public Builder setMinimumLatency(long t){v.latency=t;return this;}public Builder setRequiredNetwork(NetworkRequest n){v.network=n;return this;}public JobInfo build(){return v;}}}
